learn=[('Pause a real tool request', 'canUseTool receives the actual tool name, input and callback context. The SDK waits on a promise while the browser shows the request. No approval is granted merely because the dialog is visible.'), ('Approve or edit before execution', 'Approve once returns the original input. Approve with changes rewrites the output to reviewed.txt and uses the student-edited content. Independent host checks show what the actual Write created.'), ('Remember within the current session', 'Inspect actual SDK suggestions and the proposed session-scoped updates. Remember returns eligible acceptEdits or Write rule updates through updatedPermissions. Compare two writes with one remembered approval against approving each write once.'), ('Reject, suggest or redirect', 'A rejection message reaches the model as tool feedback. A suggestion guides it to read the lesson instead. Redirect blocks the current write and sends a separate user instruction on the same live Query after the current turn ends.'), ('Build the browser approval round trip', 'The server streams SSE data frames to the browser; POST /api/approve resolves one pending request ID. The dialog displays tool-specific input, toolUseID, deadline and whether the output existed before review.'), ('Handle cancellation and earlier approval', 'Abort or timeout resolves and removes pending requests. Stale decisions cannot be replayed. Pre-approved Write calls never reach the callback. The terminal example uses the same y/n decision shape for a bounded create/delete exercise.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3130\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Use Node.js 24+, a supported model and API credit. Windows may require Git Bash. Python is needed only to regenerate the student pages.', 'node --version\nnpm --version'), ('Install and create your .env file', 'From presentations enter this application, install locked dependencies, preserve an existing .env and enter your model key privately.', 'cd .\\agent-sdk\\lesson30-ui-approvals\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start the web application', 'Keep the terminal open, visit port 3130 and use the navigation buttons to explore the five student pages.', 'npm start\n# http://127.0.0.1:3130'), ('Use the actual approval dialog', 'Choose Approve once and run. Inspect the requested Write and click Approve once. Repeat with Approve with changes, edit the content and inspect reviewed.txt in the independent evidence. For an explicitly scripted CLI demonstration:', 'npm run sample:env -- approve --decision=approve\nnpm run sample:env -- change --decision=change'), ('Compare remember and refusal responses', 'Use Remember versus Approve once twice. Inspect actual callback counts, suggestions and session updates. Then try Reject, Suggest and Redirect using the corresponding buttons. Redirect uses the same Query for a separate task.', 'npm run sample:env -- remember --decision=remember\nnpm run sample:env -- reject --decision=reject\nnpm run sample:env -- redirect --decision=redirect'), ('Practise terminal approvals and cancellation', 'Run the terminal example. Enter y to create the disposable test file, then n to deny deletion. The tool request is shown before each decision. Back in the web app compare Pre-approved Write with Cancel while pending.', 'npm run terminal\n# First request: y\n# Delete request: n\nnpm test')]
specs=[('Validate the classroom task', 'src/modes.ts', 'export function validateConfig', 'The host accepts a fixed task name and prediction. Browser input cannot replace the SDK configuration or introduce arbitrary filesystem operations.', 0, 1, 7), ('Create an isolated lab workspace', 'src/workspace.ts', 'const root =', 'Create disposable project, home and SDK directories. The immutable fixture and output files are checked independently before bounded cleanup.', 1, 4, 7), ('Start a streaming SDK query', 'src/agent.ts', 'const active = query', 'One query owns the real model/tool loop. The streaming input stays alive so a later redirect can send a distinct user instruction without starting a second session.', 1, 2, 3), ('Receive a real permission callback', 'src/agent.ts', 'canUseTool: async', 'An unresolved tool request reaches canUseTool with its real input and context. Earlier allow rules can bypass this callback, as shown by the pre-approved comparison.', 2, 1, 8), ('Register the pending resolver before SSE', 'src/approvals.ts', 'pending.set(id,', 'Register the single-use resolver before emitting the request. This prevents a fast browser click from arriving before a pending entry exists.', 1, 3, 10), ('Send and render the SSE request', 'src/client.ts', 'if (e.type === "approval-request")', 'The browser receives the SSE data event and displays the actual tool, arguments, tool-use identifier, deadline and file state. Display alone does not approve execution.', 1, 0, 8), ('POST the reviewer decision', 'src/client.ts', 'const response = await fetch', 'The browser posts an approval ID and action. Edited content has a bounded length; the server chooses the fixed reviewed output path.', 0, 1, 8), ('Resolve one pending approval', 'src/approvals.ts', 'export function resolveApproval', 'Reject missing or replayed IDs and unavailable remember choices. Settling removes the pending entry and cancels timeout and abort listeners.', 1, 3, 7), ('Approve with validated changes', 'src/agent.ts', 'const updatedInput =', 'The host rewrites the Write path to reviewed.txt and inserts edited content. Validate the resulting request again before returning allow and updatedInput.', 1, 2, 8), ('Remember an SDK-derived session rule', 'src/agent.ts', 'permissionUpdates.push(...proposed);', 'Eligible actual SDK acceptEdits or Write addRules suggestions become session-scoped updates. Honour suppressAlwaysAllowRule. The host guard still bounds every tool, even after a permission update.', 1, 2, 8), ('Reject or suggest an alternative', 'src/agent.ts', 'redirectRequested = decision.action', 'A deny result explains the refusal. Suggest includes read-only guidance, while redirect asks the model to end this turn and await a separate user instruction.', 1, 2, 8), ('Send a distinct redirected task', 'src/agent.ts', 'redirectSent = true;', 'After the first actual result, release a new input message on the same Query. Keep the two result/session identifiers to prove the continuity.', 1, 2, 9), ('Verify outputs and clean pending state', 'src/agent.ts', 'const files = await workspace.inspect();', 'Inspect result.txt, reviewed.txt, second.txt and the unchanged fixture. Compare actual callback counts, returned permissions, cancellation and pending-count evidence.', 4, 1, 9)]
document('/','Approvals in <em>your UI.</em>','Inspect real tool requests, decide in the browser and verify actual execution.','<div class="flow"><div><b>01 · Inspect</b><p>Read the actual tool input</p></div><span>→</span><div><b>02 · Decide</b><p>Approve, edit or refuse</p></div><span>→</span><div><b>03 · Verify</b><p>Inspect actual results and files</p></div></div><section class="panel" id="controls"><h2>Explore approvals in your UI</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Approval experiment</label><select id="mode"><option value="approve">Approve once · one pending Write</option><option value="change">Approve with changes · reviewed.txt</option><option value="remember">Remember · session rule for two writes</option><option value="once-twice">Approve once twice · compare callback counts</option><option value="reject">Reject · model receives denial</option><option value="suggest">Suggest · read instead of writing</option><option value="redirect">Redirect · a separate task on one Query</option><option value="preapproved">Pre-approved Write · no callback</option><option value="cancel">Cancel while approval is pending</option></select><label for="prediction">Predict the actual task outcome</label><select id="prediction"><option value="execute">Execute · requested actions complete</option><option value="block">Block · no requested action completes</option><option value="mixed">Mixed · some actions execute and some are denied</option><option value="observe">Observe · inspect runtime-dependent behavior</option></select><button id="run" class="primary" disabled>Run approval experiment →</button><p class="meta">The experiment sets the task; your buttons decide what the real callback returns. Each query uses disposable files. Requests expire after two minutes. No browser decision is submitted automatically.</p></section><section class="step" id="review-panel" hidden><h2>Review the actual pending tool request</h2><div id="review-plan"><pre class="json-view"><code id="approval-input" class="language-json">{}</code></pre></div><p id="review-status" class="note" aria-live="polite"></p><label for="edited-content">Content for Approve with changes · output becomes reviewed.txt</label><textarea id="edited-content" rows="2">REVIEWED-30\n</textarea><div class="actions"><button class="approval-action primary" data-action="approve" id="decision-approve">Approve once</button><button class="approval-action " data-action="change" id="decision-change">Approve with changes</button><button class="approval-action " data-action="remember" id="decision-remember">Approve and remember</button><button class="approval-action " data-action="reject" id="decision-reject">Reject</button><button class="approval-action " data-action="suggest" id="decision-suggest">Suggest read instead</button><button class="approval-action " data-action="redirect" id="decision-redirect">Redirect task</button><button class="approval-action " data-action="cancel" id="decision-cancel">Cancel run</button></div><p id="remember-summary" class="meta"></p><details><summary>SDK suggestions and proposed session permissions</summary><pre class="json-view"><code id="approval-permissions" class="language-json">{}</code></pre></details><pre class="json-view"><code id="decision-json" class="language-json">{}</code></pre><p>Only the decision returned to the SDK releases this tool request. Remember is disabled if no eligible suggestion exists or suppressAlwaysAllowRule is set.</p></section><div class="workspace"><section class="panel" id="outcome"><h2 id="status" aria-live="polite">Ready</h2><p>Latest SDK-reported cost: <strong id="cost">—</strong></p><p class="meta">Session: <span id="session">—</span></p><div id="answer" class="markdown-body"></div><p id="notice" class="note"></p></section><section class="panel" id="option-panel"><h2>Options actually passed</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Compare the requested permissionMode with the SDK-reported mode. Compare these options with the actual approval requests.</p></section></div><section class="step" id="pipeline-panel"><h2>Six reviewer responses</h2><p>Inspect the request, choose a response and verify the actual result.</p><div class="grid"><article class="card"><h3>Approve once</h3><p>Return allow plus the original updatedInput.</p></article><article class="card"><h3>Approve with changes</h3><p>Return allow with an edited path and content, validated on the host.</p></article><article class="card"><h3>Approve and remember</h3><p>Return allow plus eligible SDK-derived session updatedPermissions.</p></article><article class="card"><h3>Reject</h3><p>Return deny and a reason that Claude can read.</p></article><article class="card"><h3>Suggest alternative</h3><p>Return deny with guidance to read the fixture instead.</p></article><article class="card"><h3>Redirect entirely</h3><p>Deny the current Write, then send a distinct streaming user message.</p></article></div></section><section class="step" id="configuration-panel"><h2>Actual approval configuration</h2><label for="configuration-file">Configuration projection</label><select id="configuration-file"></select><pre class="json-view"><code id="configuration-content" class="language-json">{}</code></pre><p>The query starts in default mode. Remember can apply the SDK-proposed acceptEdits mode or a Write rule to the current session.</p></section><section class="step" id="discovery-panel"><h2>Actual SDK initialization</h2><pre class="json-view"><code id="discovery" class="language-json">{}</code></pre><p>This is the SDK initialization payload. A requested mode and a reported mode are separate evidence.</p></section><section class="step" id="trace-panel"><h2>Actual hooks, callback calls and turns</h2><pre class="json-view"><code id="trace" class="language-json">{}</code></pre><p>Turn numbers distinguish the original task from a separate redirected message. The host guard bounds the three possible outputs and the fixture read.</p></section><section class="step" id="native-panel"><h2>Actual native tool feedback</h2><pre class="json-view"><code id="native" class="language-json">{}</code></pre><p>A denied Write can coexist with a successful final explanation. Inspect the actual attempt, callback decision and native feedback.</p></section><section class="step" id="warning-panel"><h2>Actual SDK warning codes</h2><pre class="json-view"><code id="warnings" class="language-json">{}</code></pre><p>Warnings describe potentially shadowed callbacks. They are not a complete audit of mode decisions or classifier invocations.</p></section><section class="step" id="evidence-panel"><h2>Decisions, session and independent file evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><p>Inspect actual decisions, callback counts, session IDs, permission updates, cancellation and independent output files.</p></section><section class="step" id="comparison-panel"><h2>Compare this browser’s approval experiments</h2><p id="verdict">Predict execute, block, mixed or observe before running. Use the corresponding decision button to follow the selected experiment.</p><div class="table"><table><thead><tr><th>Experiment</th><th>Reference behavior</th><th>Prediction</th><th>Observed</th><th>Callbacks</th><th>Completed</th><th>Fixture</th></tr></thead><tbody id="history"></tbody></table></div><button id="download">Download redacted observations</button></section><section class="step" id="event-panel"><h2>Actual SDK messages</h2><ul id="events"></ul></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Turn SDK permission requests into understandable reviewer controls.',cards(learn))
